#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0 OR MIT
# Copyright (c) 2015-2026 Sebastien Rousseau
#
# Keep the committed shell completions in step with the plugin manifests.
#
# Every completion script is generated by tools/docs/gen_completions.py from
# lib/dot/data/commands.txt (itself generated from plugins/*/dot-plugin.toml)
# and checked byte-for-byte; none is hand-maintained (ADR-020, N0.4):
#
#   defaults/dot_local/share/bash-completion/completions/dot   bash
#   share/completions/zsh/_dot                                  zsh
#   defaults/dot_config/fish/completions/dot.fish               fish
#   defaults/dot_config/nushell/completions.nu                  nushell
#   share/completions/powershell/dot.ps1                        PowerShell
#
# The release tarball and `make install` take the same files through
# --outdir (tools/release/stage-dot.sh).
#
# Usage:
#   tools/docs/generate-completions.sh                 # rewrite all five
#   tools/docs/generate-completions.sh --check         # exit 1 when one is stale
#   tools/docs/generate-completions.sh --outdir DIR    # write them under DIR
#
# Exit codes:
#   0  written / in sync
#   1  --check mode and drift detected
#   2  bad usage
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$REPO_ROOT"

case "${1:-}" in
  "") exec python3 tools/docs/gen_completions.py ;;
  --check)
    if python3 tools/docs/gen_completions.py --check; then
      echo "completions are in sync (all five generated from the manifests)"
      exit 0
    fi
    echo "Run tools/docs/generate-completions.sh (or make completions)." >&2
    exit 1
    ;;
  --outdir)
    [[ $# -ge 2 ]] || {
      echo "--outdir needs a path" >&2
      exit 2
    }
    exec python3 tools/docs/gen_completions.py --outdir "$2"
    ;;
  -h | --help) sed -n '5,28p' "$0" | sed 's/^# \{0,1\}//' ;;
  *)
    echo "unknown flag: $1" >&2
    exit 2
    ;;
esac
